={
  "query": "query { me { user_books(where: { status_id: { _eq: 3 }, updated_at: { _gt: \"{{ $json.lastChecked }}\" } }, order_by: { updated_at: asc }) { id updated_at rating book { title contributions { author { name } } editions(limit: 1, order_by: { users_count: desc }) { isbn_13 isbn_10 } } } } }"
}

parameters.jsCode:
const data = $input.first().json;
const userBooks = data?.data?.me?.[0]?.user_books ?? [];

if (userBooks.length === 0) {
  return [];
}

return userBooks.map(ub => {
  const book = ub.book;
  const title = book?.title ?? 'Unknown Title';
  const authors = (book?.contributions ?? []).map(c => c.author?.name).filter(Boolean);
  const author = authors.join(', ') || null;
  const editions = book?.editions ?? [];
  const isbn13 = editions[0]?.isbn_13 ?? null;
  const isbn10 = editions[0]?.isbn_10 ?? null;
  const isbn = isbn13 || isbn10 || null;
  const rating = ub.rating ?? null;
  const updatedAt = ub.updated_at;

  let summary = `Finished reading: ${title}`;
  if (author) summary += ` by ${author}`;
  if (rating !== null) {
    const stars = Math.round(rating);
    summary += ` ${'★'.repeat(stars)}${'☆'.repeat(5 - stars)} (${rating}/5)`;
  }

  const readOfProps = { name: [title] };
  if (author) readOfProps.author = [author];
  if (isbn) readOfProps.uid = [`isbn:${isbn}`];

  const micropubBody = {
    type: ['h-entry'],
    properties: {
      summary: [summary],
      'read-status': ['finished'],
      'read-of': [{ type: ['h-cite'], properties: readOfProps }],
      category: ['book'],
      published: [updatedAt],
      visibility: ['public'],
      'post-status': ['published']
    }
  };

  return { json: { micropubBody, updatedAt, title } };
});

const workflowStaticData = $getWorkflowStaticData('global');
workflowStaticData.lastChecked = new Date().toISOString();
return [{ json: { updated: true, lastChecked: workflowStaticData.lastChecked } }];
